from schema import And, Or, Schema, SchemaError


def build_catalog(rows):
    name = And(str, lambda value: re.fullmatch(r"[a-z]+", value) is not None)
    try:
        validated = Schema([{"key": name, "value": Or(str, int, bool, type(None))}]).validate(rows)
    except SchemaError:
        return None

    # Build keys in first-occurrence order, but values from last occurrence
    keys, values = [], []
    seen_keys = set()
    for row in validated:
        key = row["key"]
        if key not in seen_keys:
            keys.append(key)
            values.append(row["value"])  # First occurrence value
            seen_keys.add(key)
        else:
            # Update value to last occurrence
            pos = keys.index(key)
            values[pos] = row["value"]

    return {"keys": keys, "values": values}

