def build_catalog(rows):
    name = And(str, lambda value: re.fullmatch(r"[a-z]+", value) is not None)
    try:
        validated = Schema([{"key": name, "value": Or(str, int, bool, type(None))}]).validate(rows)
    except SchemaError:
        return None
    keys, values = {}, []
    first_index = {}
    for row in validated:
        key = row["key"]
        value = row["value"]
        if key not in first_index:
            first_index[key] = len(values)
            keys[key] = len(values)
        # Always update the value to the last occurrence
        keys[key] = len(values)
        if key not in keys or keys[key] == len(values):
            values.append(value)
    # Rebuild keys list in first-occurrence order
    result_keys = []
    result_values = []
    for key in sorted(first_index.keys(), key=lambda k: first_index[k]):
        result_keys.append(key)
        result_values.append(values[first_index[key]])
    return {"keys": result_keys, "values": result_values}

