    try:
        Schema.validate(rows)
    except Schema.SchemaError:
        return None

    # Track first occurrence order and last value for each key
    key_order = []  # Preserve order by first occurrence
    last_values = {}  # Last value for each key

    for row in rows:
        key = row["key"]
        value = row["value"]

        if key not in last_values:
            key_order.append(key)

        last_values[key] = value

    return {
        "keys": key_order,
        "values": [last_values[k] for k in key_order]
    }

