import re
from schema import And, Or, Schema, SchemaError


def build_catalog(rows):
    name = And(str, lambda value: re.fullmatch(r"[a-z]+", value) is not None)
    try:
        validated = Schema([{"key": name, "value": Or(str, int, bool, type(None))}]).validate(rows)
    except SchemaError:
        return None

    # Track first occurrence position (index in original rows) for ordering keys
    first_occurrence = {}
    # Store values by key, always updating to last occurrence
    values_by_key = {}

    for idx, row in enumerate(validated):
        key = row["key"]
        value = row["value"]
        if key not in first_occurrence:
            first_occurrence[key] = idx
        values_by_key[key] = value

    # Build keys list in first-occurrence order (by position)
    keys = []
    for key in sorted(first_occurrence.keys(), key=lambda k: first_occurrence[k]):
        keys.append(key)

    # Get values in same order from values_by_key
    values = [values_by_key[k] for k in keys]

    return {"keys": keys, "values": values}

